from rules import active_deps, eligible


def solve(data):
    packages = data.get('packages', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = data.get('features', [])
    names = sorted(packages)

    constraints = {}
    for name, bounds in data.get('roots', {}).items():
        constraints.setdefault(name, []).append(tuple(bounds))

    best_score = None
    best_versions = None

    def is_acyclic(assignments):
        color = {}

        def visit(name):
            state = color.get(name, 0)
            if state == 1:
                return False
            if state == 2:
                return True
            color[name] = 1
            for dep in active_deps(assignments[name], features):
                target = dep['name']
                if target not in assignments or not visit(target):
                    return False
            color[name] = 2
            return True

        return all(visit(name) for name in assignments if color.get(name, 0) == 0)

    def search(assignments, limits):
        nonlocal best_score, best_versions
        pending = sorted(name for name in limits if name not in assignments)
        if not pending:
            if not is_acyclic(assignments):
                return
            versions = {name: row['version'] for name, row in assignments.items()}
            score = tuple(versions.get(name, -1) for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = versions
            return

        name = pending[0]
        rows = packages.get(name, [])
        choices = [row for row in rows if eligible(row, limits[name], blocked.get(name, []), pins.get(name))]
        choices.sort(key=lambda row: row['version'], reverse=True)
        for row in choices:
            next_assignments = dict(assignments)
            next_assignments[name] = row
            next_limits = {key: list(value) for key, value in limits.items()}
            valid = True
            for dep in active_deps(row, features):
                target = dep['name']
                next_limits.setdefault(target, []).append((dep['min'], dep['max']))
                selected = next_assignments.get(target)
                if selected is not None and not eligible(
                    selected, next_limits[target], blocked.get(target, []), pins.get(target)
                ):
                    valid = False
                    break
            if valid:
                search(next_assignments, next_limits)

    search({}, constraints)
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

def active_deps(row, features):
    enabled = set(features)
    return [
        dep for dep in row.get('deps', [])
        if not dep.get('feature') or dep.get('feature') in enabled
    ]


def eligible(row, limits, blocked, pin):
    version = row['version']
    if pin is not None and version != pin:
        return False
    if version in blocked:
        return False
    return all(low <= version <= high for low, high in limits)
